<script lang="ts">
 import {onMount} from 'svelte';import * as api from '../../bindings';import type {CaseOperations} from '../operations/controller.svelte';import EvidencePicker from '../pickers/EvidencePicker.svelte';import RecordPicker from '../pickers/EntityPicker.svelte';import ErrorNotice from '../../ErrorNotice.svelte';import {LocalArchiveSource,boundedDecompress} from './local-source';import {preferences} from '../../stores/preferences.svelte';
 import type {Map as MapInstance,StyleSpecification,GeoJSONSource} from 'maplibre-gl';
 let {generation,active,operations,onopen,onGraph,onReport}:{generation:number;active:boolean;operations:CaseOperations;onopen:(kind:string,id:string)=>void;onGraph:(id:string)=>void;onReport:(id:string)=>void}=$props();
 let container:HTMLDivElement;let ready=$state(false);let map:MapInstance|undefined;let importJob=$state<string|null>(null);let removeProtocol:(()=>void)|undefined;let live=true,version=0;
 let reviewing=$state(false);
 let worldSelection=$state<api.WorldSelectionView|null>(null),metadataConsent=$state(false),worldConsent=$state(false);
 let archives=$state<api.MapArchiveView[]>([]),archiveId=$state(''),locations=$state<api.LocationPageView|null>(null),offset=$state(0),selected=$state<api.LocationView|null>(null),query=$state(''),busy=$state(false),error=$state<api.CommandError|null>(null),message=$state(''),nativeSelection=$state<api.MapSelectionView|null>(null),credits=$state(''),consent=$state(false),camera=$state<api.MapStateView|null>(null),showLocations=$state(true);
 let observationId=$state(''),entityId=$state(''),entityName=$state(''),label=$state(''),longitude=$state(0),latitude=$state(0),uncertainty=$state(''),rationale=$state(''),draw=$state(false);
 let archive=$derived(archives.find(a=>a.id===archiveId));let visible=$derived((locations?.rows??[]).filter(l=>`${l.label} ${l.uncertainty}`.toLowerCase().includes(query.toLowerCase())));
 onMount(()=>{void refresh();return()=>{live=false;version++;map?.remove();removeProtocol?.();};});
 $effect(()=>{if(active&&ready){archiveId;void initialize();}else map?.stop();});
 $effect(()=>{visible;showLocations;updatePoints();});
 export async function refresh(){try{const[resources,points,state]=await Promise.all([api.mapArchives(),api.locationPage(generation,offset),api.mapStateRead(generation)]);if(live){archives=resources;locations=points;if(!camera){camera=state;ready=true;archiveId=state.archive_id??'';showLocations=state.show_locations;}if(state.archive_id&&!resources.some(a=>a.id===state.archive_id))message='Saved basemap is unavailable. Locations and camera remain in the case; import the same archive or choose another.';updatePoints();}}catch(raw){if(live)error=api.asCommandError(raw);}}
 async function initialize(){const current=++version;try{
  const gl=await import('maplibre-gl');const {PMTiles,Protocol}=await import('pmtiles');const worker=await import('maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url');await import('maplibre-gl/dist/maplibre-gl.css');if(!live||current!==version)return;
  const old=map;if(old){const center=old.getCenter();camera={...camera!,longitude:center.lng,latitude:center.lat,zoom:old.getZoom(),bearing:old.getBearing(),pitch:old.getPitch()};old.remove();}removeProtocol?.();gl.setWorkerUrl(worker.default);
  const protocol=new Protocol();if(archive){protocol.add(new PMTiles(new LocalArchiveSource(archive),undefined,boundedDecompress));}gl.addProtocol('pmtiles',protocol.tile);removeProtocol=()=>gl.removeProtocol('pmtiles');
  const style:StyleSpecification={version:8,sources:{},layers:[{id:'background',type:'background',paint:{'background-color':document.documentElement.dataset.theme==='light'?'#e5e8ec':'#171d24'}}]};
  if(archive){style.sources.basemap={type:archive.tile_type===1?'vector':'raster',url:`pmtiles://kokin-local://${archive.id}`};if(archive.tile_type!==1){style.layers.push({id:'raster',source:'basemap',type:'raster'});}else{for(const layer of archive.layers){if(['water','earth','landuse','landcover','buildings','building'].includes(layer))style.layers.push({id:`base-${layer}`,source:'basemap','source-layer':layer,type:'fill',paint:{'fill-color':layer==='water'?'#334d63':'#303d35','fill-opacity':0.8}});else if(['roads','transportation','boundaries','boundary','waterway'].includes(layer))style.layers.push({id:`base-${layer}`,source:'basemap','source-layer':layer,type:'line',paint:{'line-color':'#8f969e','line-width':1}});}}}
  map=new gl.Map({container,style,center:[camera!.longitude,camera!.latitude],zoom:camera!.zoom,bearing:camera!.bearing,pitch:camera!.pitch,attributionControl:false,renderWorldCopies:false,canvasContextAttributes:{preserveDrawingBuffer:true},maxZoom:archive?.max_zoom??22,fadeDuration:0,transformRequest:url=>{if(!url.startsWith('pmtiles://kokin-local://'))throw new Error('Remote map URLs are prohibited');return{url};}});
  map.on('load',updatePoints);map.on('error',e=>{if(live)message=`Map rendering/read limitation: ${e.error.message}. The location list remains available.`;});map.on('click',event=>{if(draw){longitude=event.lngLat.lng;latitude=event.lngLat.lat;draw=false;message='Coordinates placed in the form only. Choose source evidence, uncertainty and rationale before recording.';return;}const features=map!.queryRenderedFeatures(event.point,{layers:map!.getLayer('locations')?['locations']:[]});const id=features[0]?.properties?.id;if(typeof id==='string')selected=locations?.rows.find(l=>l.id===id)??null;});
 }catch(raw){if(live&&current===version)error=api.asCommandError(raw);}}
 function updatePoints(){if(!map||!map.isStyleLoaded())return;const data={type:'FeatureCollection' as const,features:(showLocations?visible:[]).filter(l=>Math.abs(l.latitude)<=85.0511).map(l=>({type:'Feature' as const,geometry:{type:'Point' as const,coordinates:[l.longitude,l.latitude]},properties:{id:l.id}}))};const source=map.getSource('locations');if(source&&'setData'in source)(source as GeoJSONSource).setData(data);else{map.addSource('locations',{type:'geojson',data});map.addLayer({id:'locations',source:'locations',type:'circle',paint:{'circle-radius':7,'circle-color':'#88aee8','circle-stroke-width':2,'circle-stroke-color':'#172031'}});}}
 async function choose(){error=null;try{nativeSelection=await api.mapSelect();consent=false;credits='';}catch(raw){error=api.asCommandError(raw);}}
 async function importArchive(){if(!nativeSelection||!consent||!credits.trim())return;busy=true;error=null;try{const job=await api.mapImport({selection:nativeSelection.selection,attribution:credits,consent});importJob=job;let status=await api.resourceStatus(job);while(live&&status.status==='running'){message=`${status.stage}: ${(status.transferred/1024/1024).toFixed(1)} MiB`;await new Promise(r=>setTimeout(r,300));status=await api.resourceStatus(job);}if(!live)return;if(status.status!=='completed')throw new Error(status.error??'Map import did not complete');archives=await api.mapArchives();archiveId=status.resource_id;nativeSelection=null;message='Local archive imported. Attribution remains visible; no tile requests leave this app.';}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live){busy=false;importJob=null;}}}

 async function reviewWorld(){reviewing=true;busy=true;error=null;worldSelection=null;worldConsent=false;try{const result=await api.mapWorldReview(metadataConsent);if(live)worldSelection=result;}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live){busy=false;reviewing=false;}}}
 async function installWorld(){if(!worldSelection||!worldConsent)return;busy=true;error=null;try{const job=await api.mapWorldInstall(worldSelection.selection,worldConsent);importJob=job;let result=await api.resourceStatus(job);while(live&&result.status==='running'){message=`World basemap: ${result.stage} · ${(result.transferred/1024/1024).toFixed(1)} / ${(result.bytes/1024/1024).toFixed(1)} MiB`;await new Promise(r=>setTimeout(r,300));result=await api.resourceStatus(job);}if(!live)return;if(result.status!=='completed')throw new Error(result.error??'World install failed');archives=await api.mapArchives();archiveId=result.resource_id;worldSelection=null;message='World z0–z6 installed. Panning uses only local range reads.';}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live){busy=false;importJob=null;}}}

 async function create(event:SubmitEvent){event.preventDefault();busy=true;error=null;try{await api.locationCreate(generation,{observation_id:observationId,entity_id:entityId||null,label,longitude,latitude,uncertainty,rationale});if(live){label='';rationale='';uncertainty='';await refresh();message='Grounded location recorded; source evidence was not modified.';}}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live)busy=false;}}
 async function saveCamera(){if(!map||!camera)return;const center=map.getCenter();try{camera=await api.mapStateSave(generation,{revision:camera.revision,archive_id:archiveId||null,longitude:center.lng,latitude:center.lat,zoom:map.getZoom(),bearing:map.getBearing(),pitch:map.getPitch(),show_locations:showLocations});message='Map camera and layer preference saved in the encrypted case.';}catch(raw){error=api.asCommandError(raw);}}
 function focus(l:api.LocationView){selected=l;if(Math.abs(l.latitude)>85.0511){message='This exact latitude lies outside the Mercator canvas. It remains available in the location list.';return;}map?.easeTo({center:[l.longitude,l.latitude],zoom:Math.min(archive?.max_zoom??12,8),duration:preferences.value.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?0:180});}
 async function illustration(){if(!map||!archive){message='Install a credited basemap before creating a map illustration.';return;}if(!map.loaded()){message='Wait for local map tiles to finish rendering before saving an illustration.';return;}message='';map.triggerRepaint();await new Promise<void>(resolve=>map!.once('render',()=>resolve()));if(!live||!map)return;const canvas=document.createElement('canvas');canvas.width=map.getCanvas().width;const ctx=canvas.getContext('2d');if(!ctx)return;ctx.font='14px sans-serif';const lines:string[]=[];let line='';for(const word of archive.attribution.split(/\s+/).flatMap(word=>{const parts:string[]=[];let part='';for(const char of word){if(ctx.measureText(part+char).width>canvas.width-24&&part){parts.push(part);part='';}part+=char;}if(part)parts.push(part);return parts;})){if(ctx.measureText(`${line} ${word}`).width>canvas.width-24&&line){lines.push(line);line=word;}else line=`${line} ${word}`.trim();}if(line)lines.push(line);canvas.height=map.getCanvas().height+lines.length*20+48;if(canvas.height>4096){message='Attribution is too long for this illustration size; enlarge the view or use a text report.';return;}ctx.drawImage(map.getCanvas(),0,0);ctx.fillStyle='#171d24';ctx.fillRect(0,map.getCanvas().height,canvas.width,canvas.height-map.getCanvas().height);ctx.fillStyle='#eef0f2';ctx.font='14px sans-serif';lines.forEach((line,i)=>ctx.fillText(line,12,map!.getCanvas().height+20+i*20));ctx.fillText('Analyst-rendered context: proximity is not confidence. See cited locations and uncertainty.',12,canvas.height-14);await operations.run('map_illustration',{image:canvas.toDataURL('image/png'),archive_id:archive.id,attribution:archive.attribution,location_ids:visible.map(l=>l.id)});}

</script>
<section class="map-workspace" aria-label="Offline maps" hidden={!active}><header><h2>Offline maps</h2><p>Source-grounded locations. No geocoding, remote styles, fonts or tiles. A basemap supplies context, not evidence for a conclusion.</p></header>{#if error}<ErrorNotice {error}/>{/if}{#if message}<p role="status">{message}</p>{/if}
 <div class="toolbar"><label>Local basemap<select bind:value={archiveId}><option value="">No basemap</option>{#each archives as a}<option value={a.id}>{a.id.slice(0,12)} · z{a.min_zoom}–z{a.max_zoom}</option>{/each}</select></label><button type="button" disabled={busy} onclick={choose}>Choose local PMTiles archive</button><button type="button" onclick={()=>map?.zoomIn({duration:0})}>Zoom in</button><button type="button" onclick={()=>map?.zoomOut({duration:0})}>Zoom out</button><button type="button" onclick={()=>{if(visible.length){const xs=visible.map(l=>l.longitude),ys=visible.filter(l=>Math.abs(l.latitude)<=85.0511).map(l=>l.latitude);if(ys.length)map?.fitBounds([[Math.min(...xs),Math.min(...ys)],[Math.max(...xs),Math.max(...ys)]],{padding:40,duration:0,maxZoom:archive?.max_zoom??12});}}}>Fit visible locations</button><button type="button" onclick={saveCamera}>Save map view</button><button type="button" disabled={operations.busy} onclick={illustration}>Save cited map illustration</button></div>
 {#if nativeSelection}<section class="import"><h3>Review basemap import</h3><p>{nativeSelection.filename} · {(nativeSelection.bytes/1024/1024).toFixed(1)} MiB · z{nativeSelection.min_zoom}–z{nativeSelection.max_zoom}. Destination: {nativeSelection.destination}</p><p>Basemaps stay outside encrypted cases and are excluded from packages. Only public basemap data should be imported here.</p><label>Required attribution / license credits<textarea bind:value={credits}></textarea></label><label class="check"><input type="checkbox" bind:checked={consent}/>I approve this size, destination and attribution.</label><button type="button" disabled={busy||!consent||!credits.trim()} onclick={importArchive}>Import local basemap</button></section>{/if}
 <details><summary>Install world basemap z0–z6</summary><p>Optional public resource from https://build.protomaps.com/20261011.pmtiles. First review sends bounded directory/metadata range requests to Protomaps, disclosing this URL and your network address, with no case coordinates or evidence. The second action downloads only z0–z6 tiles (128 MiB cap). The full planet file is never downloaded.</p><label class="check"><input type="checkbox" bind:checked={metadataConsent}/>Approve public metadata requests to calculate the exact transfer size.</label><button type="button" disabled={busy||!metadataConsent} onclick={reviewWorld}>Review world basemap size</button>{#if reviewing}<button type="button" onclick={async()=>{try{const job=(await api.resourceJobs()).find(r=>r.status==='running'&&r.resource_id==='world-review');if(job)await api.resourceCancel(job.operation_id);}catch(raw){error=api.asCommandError(raw);}}}>Cancel world metadata review</button>{/if}{#if worldSelection}<p>Tile transfer: {(worldSelection.download_bytes/1024/1024).toFixed(1)} MiB. Local archive: at most {(worldSelection.maximum_output_bytes/1024/1024).toFixed(1)} MiB. Destination: {worldSelection.destination}</p><p>Source identity: {worldSelection.url} · ETag {worldSelection.etag}. Kokin checks ETag consistency across every range and hashes the assembled archive. This is not a publisher's digital signature. © OpenStreetMap contributors (ODbL), Natural Earth, Protomaps.</p><label class="check"><input type="checkbox" bind:checked={worldConsent}/>Approve this size, destination and credited public basemap download.</label><button type="button" disabled={busy||!worldConsent} onclick={installWorld}>Download world z0–z6 basemap</button>{/if}</details>
 <div>{#if importJob&&busy}<button type="button" onclick={()=>api.resourceCancel(importJob!).catch(raw=>error=api.asCommandError(raw))}>Cancel basemap import</button>{/if}</div>
 <div class="map" bind:this={container} aria-label="Offline map canvas"></div><p class="attribution">MapLibre · {archive?.attribution??'No basemap installed. Import a compatible local archive; grounded locations remain usable in the list.'}</p>
 <div class="toolbar"><label>Filter visible locations<input type="search" bind:value={query}/></label><label class="check"><input type="checkbox" bind:checked={showLocations}/>Show location layer</label><p>{visible.length} visible / {locations?.rows.length??0} loaded / {locations?.total??0} stored. Filters change the view only. Latitudes outside Mercator bounds remain in the list.</p></div>
 <details><summary>Record a grounded point</summary><form onsubmit={create}><label>Location label<input bind:value={label} required maxlength="120"/></label><div class="coordinates"><label>Longitude<input type="number" min="-180" max="180" step="any" bind:value={longitude} required/></label><label>Latitude<input type="number" min="-90" max="90" step="any" bind:value={latitude} required/></label></div><button type="button" aria-pressed={draw} onclick={()=>draw=!draw}>{draw?'Cancel coordinate pick':'Pick coordinates on canvas'}</button><EvidencePicker onchoose={c=>observationId=c.id} oninspect={onopen}/>{#if observationId}<p>Selected source observation: {observationId}</p>{/if}<RecordPicker label="Optional linked entity" onchoose={entity=>{entityId=entity.id;entityName=entity.name;}}/>{#if entityId}<p>{entityName}<button type="button" onclick={()=>{entityId='';entityName='';}}>Remove entity link</button></p>{/if}<label>Uncertainty / precision description<textarea bind:value={uncertainty} required></textarea></label><label>Why this source supports these coordinates<textarea bind:value={rationale} required></textarea></label><button disabled={busy||!observationId||operations.busy}>Record source-grounded location</button></form></details>
 <section aria-label="Location list alternative"><h3>Locations</h3>{#each visible as l}<article><button type="button" onclick={()=>focus(l)}>{l.label} · {l.latitude}, {l.longitude}</button><p>{l.uncertainty}</p>{#if selected?.id===l.id}<p>{l.rationale}</p><button type="button" onclick={()=>onopen('observation',l.observation_id)}>Inspect location evidence</button>{#if l.entity_id}<button type="button" onclick={()=>onopen('entity',l.entity_id!)}>Inspect linked entity</button><button type="button" onclick={()=>onGraph(l.entity_id!)}>Open linked entity in Graph</button>{/if}<button type="button" onclick={()=>onReport(l.observation_id)}>Cite location evidence in report</button>{/if}</article>{/each}<button type="button" disabled={offset===0} onclick={()=>{offset=Math.max(0,offset-1000);void refresh();}}>Previous locations</button><button type="button" disabled={!locations||offset+1000>=locations.total} onclick={()=>{offset+=1000;void refresh();}}>Next locations</button></section>
</section>
<style>.map-workspace{min-width:0}.map{height:520px;width:100%;border:1px solid var(--border);border-radius:var(--radius-panel);overflow:hidden;margin-top:20px}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}p{max-width:85ch;color:var(--foreground-secondary);line-height:1.6}.attribution{font-size:12px;border:1px solid var(--border);padding:12px}label{display:grid;gap:8px}.check{display:flex;align-items:center}details,.import{margin:24px 0;padding:20px;border:1px solid var(--border);border-radius:var(--radius-panel)}summary{font-weight:600;cursor:pointer}form{display:grid;gap:16px;margin-top:20px}.coordinates{display:grid;grid-template-columns:1fr 1fr;gap:16px}textarea{min-height:90px}article{padding:16px 0;border-bottom:1px solid var(--border)}.map:focus-within{outline:2px solid var(--accent)}@media(max-width:1000px){.map{height:360px}.coordinates{grid-template-columns:1fr}}</style>
